S = "Hakeem Force Academy"
QS = [
(S, "According to Islamic tradition, who first built the Kaaba?", ["Hazrat Adam (AS)", "Hazrat Ibrahim (AS)", "Hazrat Ismail (AS)", "Hazrat Nuh (AS)"], 0,
 "Islamic tradition says the Kaaba was first built by Hazrat Adam (AS), and later rebuilt by Hazrat Ibrahim (AS) with his son Ismail (AS). Many candidates and sources give this answer for the first building.",
 "Sources differ, and some Pakistani textbooks credit Ibrahim and Ismail (AS) with building it, but they rebuilt it on its old foundations.", [310, 184, 5007]),
(S, "Kabul is the capital of which country?", ["Iran", "Afghanistan", "Tajikistan", "Uzbekistan"], 1,
 "Kabul is the capital and largest city of Afghanistan.",
 "Kabul lies on the Kabul River and is close to the Khyber Pass route to Pakistan.", [2814]),
(S, "On which river is the city of Kabul located?", ["Helmand River", "Amu Darya", "Kabul River", "Kunar River"], 2,
 "The city of Kabul stands on the banks of the Kabul River.",
 "The Kabul River flows into Pakistan and joins the Indus near Attock.", [2917]),
(S, "About how many soldiers did the Quraish (disbelievers) have in the Battle of Badr?", ["300", "700", "1000", "3000"], 2,
 "The Makkan army at Badr numbered about 1000 men, against about 313 Muslims.",
 "The Muslims won the Battle of Badr in 2 AH despite being outnumbered about three to one.", [1562]),
(S, "Who led the Quraish army in the Battle of Uhud?", ["Abu Jahl", "Abu Sufyan", "Utbah", "Umayyah bin Khalaf"], 1,
 "Abu Sufyan was the commander of the Makkan army at Uhud, as Abu Jahl had been killed at Badr.",
 "Khalid bin Waleed, then on the Quraish side, led the cavalry attack that turned the battle at Uhud.", [4693]),
(S, "Kaghan Valley is located in which district of Khyber Pakhtunkhwa?", ["Swat", "Chitral", "Mansehra", "Abbottabad"], 2,
 "Kaghan Valley lies in the Mansehra district of Hazara in Khyber Pakhtunkhwa.",
 "Babusar Pass at the head of the valley connects it to Chilas in Gilgit-Baltistan.", [2817]),
(S, "Which one is different from the others: chimpanzee, ape, baboon, kangaroo, monkey?", ["Chimpanzee", "Baboon", "Kangaroo", "Monkey"], 2,
 "Chimpanzee, ape, baboon and monkey are all primates, while the kangaroo is a marsupial.",
 "Kangaroos are native to Australia and carry their young in a pouch.", [1350]),
(S, "Which one is different from the others: Karachi, Lahore, Balochistan, Rawalpindi?", ["Karachi", "Lahore", "Balochistan", "Rawalpindi"], 2,
 "Karachi, Lahore and Rawalpindi are cities, while Balochistan is a province.",
 "Balochistan is the largest province of Pakistan by area.", [446]),
(S, "The Karakoram Highway connects Pakistan with which country?", ["Afghanistan", "China", "India", "Iran"], 1,
 "The Karakoram Highway runs from Hasan Abdal in Pakistan to Kashgar in China through the Khunjerab Pass.",
 "The Khunjerab Pass, at about 4693 metres, is the highest paved border crossing in the world.", [3038, 3039]),
(S, "Which of these is another name for the Karakoram Highway?", ["Grand Trunk Road", "Friendship Highway", "Motorway M-2", "Indus Highway"], 1,
 "The Karakoram Highway is also called the Pakistan-China Friendship Highway and is numbered N-35.",
 "It is sometimes called the Eighth Wonder of the World because of the difficulty of building it.", [1159]),
(S, "Arfa Karim, the youngest Microsoft Certified Professional, belonged to which country?", ["India", "Pakistan", "Bangladesh", "Sri Lanka"], 1,
 "Arfa Abdul Karim Randhawa was a Pakistani girl from Faisalabad who became a Microsoft Certified Professional at age 9.",
 "She died in January 2012 at the age of 16, and Lahore has a software technology park tower named after her.", [773, 1700]),
(S, "In which province of Pakistan is the karez system of irrigation mainly used?", ["Punjab", "Sindh", "Balochistan", "Khyber Pakhtunkhwa"], 2,
 "A karez is an underground channel that carries water from a hillside, and it is widely used in dry Balochistan.",
 "Karez is also known as qanat in Iran and is used across Central Asia.", [2657, 2660]),
(S, "Hilal-e-Kashmir, the highest military gallantry award of Azad Kashmir, was awarded to whom?", ["Havaldar Lalak Jan", "Naik Saif Ali Janjua", "Major Raja Aziz Bhatti", "Captain Karnal Sher Khan"], 1,
 "Naik Saif Ali Janjua received it after dying in the 1947-48 war in Kashmir, and he is its only recipient.",
 "It was declared equal to the Nishan-e-Haider in 1995.", [3110]),
(S, "What is the border between Pakistan-administered and Indian-administered Kashmir called?", ["Durand Line", "Radcliffe Line", "Line of Control", "McMahon Line"], 2,
 "The ceasefire line of 1949 became the Line of Control after the Simla Agreement of 1972.",
 "The Durand Line is the Pakistan-Afghanistan border.", [1095]),
(S, "Who described Kashmir as the jugular vein of Pakistan?", ["Allama Iqbal", "Quaid-e-Azam Muhammad Ali Jinnah", "Liaquat Ali Khan", "Chaudhry Rahmat Ali"], 1,
 "The statement is credited to Quaid-e-Azam Muhammad Ali Jinnah, who stressed the strategic importance of Kashmir.",
 "Pakistan marks Kashmir Solidarity Day on 5 February each year.", [1438]),
(S, "Kathmandu is the capital of which country?", ["Bhutan", "Nepal", "Sri Lanka", "Myanmar"], 1,
 "Kathmandu is the capital and largest city of Nepal.",
 "Thimphu is the capital of Bhutan.", [990, 3527]),
(S, "Which of these countries is not a member of the Shanghai Cooperation Organisation (SCO)?", ["Tajikistan", "Kazakhstan", "Turkmenistan", "China"], 2,
 "Turkmenistan has never joined the SCO, while Tajikistan, Kazakhstan, China and Pakistan are members.",
 "Pakistan and India became full SCO members in 2017.", [4528]),
(S, "At whose house in Madinah did the camel of the Holy Prophet (PBUH) stop, so that he stayed there after the Hijrat?", ["Hazrat Abu Ayyub Ansari (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Ali (RA)", "Hazrat Saad bin Muaz (RA)"], 0,
 "The Prophet (PBUH) let his camel Qaswa choose, and it knelt near the house of Hazrat Abu Ayyub Ansari (RA), where he stayed until his mosque was built.",
 "Hazrat Abu Ayyub Ansari (RA) later died at the siege of Constantinople.", [2508]),
(S, "Who was the third Khalifa of Islam?", ["Hazrat Umar (RA)", "Hazrat Uthman (RA)", "Hazrat Ali (RA)", "Hazrat Abu Bakr (RA)"], 1,
 "The Rightly Guided Caliphs were Abu Bakr, Umar, Uthman and Ali (RA), so Hazrat Uthman (RA) was third.",
 "Hazrat Uthman (RA) is known as Ghani and had the Quran compiled in one standard copy.", [5319]),
(S, "How many Khulafa-e-Rashideen (Rightly Guided Caliphs) were there?", ["3", "4", "5", "6"], 1,
 "There were four: Abu Bakr, Umar, Uthman and Ali (RA).",
 "Their rule lasted about 30 years, from 632 to 661 CE.", [2177]),
(S, "Between the Muslims and whom was the Ghazwa Khandaq (Battle of the Trench) fought?", ["Quraish and their allied tribes", "Jews of Khyber only", "Byzantines", "Banu Qaynuqa"], 0,
 "The Quraish of Makkah joined with other Arab tribes and Jewish tribes to attack Madinah in 5 AH.",
 "The battle is also called Ghazwa Ahzab, meaning the battle of the confederates.", [1824]),
(S, "On which river is the Khanpur Dam built?", ["Haro River", "Soan River", "Jhelum River", "Kabul River"], 0,
 "Khanpur Dam is built on the Haro River in the Haripur district of Khyber Pakhtunkhwa.",
 "It supplies drinking water to Islamabad and Rawalpindi.", [555]),
(S, "Habba Khatoon was a famous poetess of which language?", ["Kashmiri", "Punjabi", "Pashto", "Sindhi"], 0,
 "Habba Khatoon was a 16th century Kashmiri poetess, known as the Nightingale of Kashmir.",
 "She was the wife of Yusuf Shah Chak, the last independent Muslim ruler of Kashmir.", [2313, 862, 2094, 2996]),
(S, "Against whom was the Khilafat Movement in India directed?", ["The British government", "The Hindu Congress", "The Sikhs", "The Mughals"], 0,
 "The movement, led by Muslims of India, opposed British treatment of the Ottoman Caliph after World War I.",
 "Maulana Muhammad Ali Jauhar and Maulana Shaukat Ali were its main leaders.", [1723]),
(S, "What is the synonym of the word justify?", ["Condemn", "Vindicate", "Ignore", "Accuse"], 1,
 "To justify means to show something to be right or reasonable, and vindicate has a similar meaning.",
 "Justification is the noun form of justify.", [3979]),
(S, "What is the antonym of the word justify?", ["Defend", "Support", "Condemn", "Explain"], 2,
 "To justify means to defend as right, and the opposite is to condemn or blame.",
 "Another opposite of justify is to criticise.", [1088]),
]
